package br.edu.imt.ecm231.p18; public class ExecutarTestes { public static void main(String[] a){int f=0;f+=run("PedidoTest",PedidoTest::executar);f+=run("ControladorPedidosIT",ControladorPedidosIT::executar);System.out.println(f==0?"RESULTADO: SUCESSO":"RESULTADO: FALHA");if(f>0)System.exit(1);} static int run(String n,Runnable r){try{r.run();System.out.println("[OK] "+n);return 0;}catch(Throwable e){System.out.println("[FALHA] "+n+" -> "+e.getMessage());return 1;}} }
